INSERT INTO `scam_tactics` (`id`, `category`, `title`, `red_flags`, `created_at`) VALUES
('SCAM_01', 'Fake Recruitment', 'Tuyển CTV chốt đơn / xem TikTok nhận tiền - Yêu cầu nạp quỹ đảm bảo', 'yêu cầu nạp tiền, nạp quỹ đảm bảo, chuyển khoản trước, lương cao bất thường, tài khoản cá nhân, hối thúc làm nhiệm vụ', '2026-07-30 04:17:13'),
('SCAM_02', 'Malware APK', 'Giả mạo Công an / Cục Thuế yêu cầu cài file APK VNeID giả mạo', 'tải file apk, link lạ đuôi .apk, công an gọi điện, cục thuế cập nhật thông tin, hướng dẫn cài ngoài app store, cấp quyền truy cập accessibility', '2026-07-30 04:17:13'),
('SCAM_03', 'Fake VietQR Bill', 'Ảnh VietQR bill chuyển khoản giả / Chuyển nhầm tiền bẫy tín dụng đen', 'bill chuyển tiền thành công nhưng tài khoản chưa tăng, font chữ bill bị lệch, yêu cầu chuyển lại tiền nhầm qua link lạ, hối thúc trả lại tiền ngay', '2026-07-30 04:17:13'),
('SCAM_04', 'Fake Shipper COD', 'Giả mạo Shipper giao hàng COD - Yêu cầu chuyển khoản tiền đơn nhận hộ', 'shipper gọi giao hàng nhưng không nhớ mua, gửi hàng ở bảo vệ yêu cầu chuyển khoản, số tiền nhỏ vài chục đến vài trăm ngàn để tạo cảm giác dễ dãi', '2026-07-30 04:17:13'),
('SCAM_05', 'Deepfake Loan', 'Deepfake video call / Giả mạo người thân hối thúc vay tiền khẩn cấp', 'video call vài giây mờ nhòe đứt đoạn, mượn tiền gấp do viện phí/tai nạn, yêu cầu chuyển vào tài khoản người thứ 3, tên tài khoản ngân hàng khác tên người thân', '2026-07-30 04:17:13');
